steps.seedCode:
const http = require('http');

// Create an HTTP server here
const server = http.createServer(requestHandler);

// Define the request handler callback function
const requestHandler = (request, response) => {
  // Set response headers here
  response.writeHead(200, { 'Content-Type': 'text/plain' });
  // Add conditional logic for different URL paths here
  if (request.url === '/') {
    response.write('Welcome to the homepage!');
  } else {
    response.write('404 Not Found');
  }
  // Write response body content here
  response.end('\nHello from Node.js HTTP server!');
};

// Make the server listen on port 3000
server.listen(3000, () => {
  console.log('Server running at http://localhost:3000');
});

